const inputPath = 'public/data/en/stats.ndjson'
const outputPath = 'public/data/ja/stats.ndjson'

console.log('英語版データを読み込んでいます...')
const content = fs.readFileSync(inputPath, { encoding: 'utf-8' })
const lines = content.split('\n').filter(line => line.length > 0)
console.log(`${lines.length} 行見つかりました。変換を開始します...`)

const NOTABLE_PATTERN = /^1 Added Passive Skill is (.+)$/

let addedCount = 0
let notableMatchedCount = 0
const notFoundNotables = new Set(Object.keys(NOTABLE_NAMES))

const outLines = lines.map(line => {
  let obj
  try {
    obj = JSON.parse(line)
  } catch (e) {
    console.error('JSON解析に失敗した行があります:', line.slice(0, 100))
    throw e
  }

  const stats = ('stats' in obj) ? obj.stats : [obj]
  for (const stat of stats) {
    for (const matcher of stat.matchers) {
      const jaText = TRANSLATIONS[matcher.string]
      if (jaText && !stat.matchers.some((m) => m.string === jaText)) {
        stat.matchers.push({ ...matcher, string: jaText })
        addedCount += 1
      }

      const notableMatch = matcher.string.match(NOTABLE_PATTERN)
      if (notableMatch) {
        const englishName = notableMatch[1]
        const japaneseName = NOTABLE_NAMES[englishName]
        if (japaneseName) {
          const jaNotableText = `パッシブスキルを1個追加: ${japaneseName}`
          if (!stat.matchers.some((m) => m.string === jaNotableText)) {
            stat.matchers.push({ ...matcher, string: jaNotableText })
            addedCount += 1
            notableMatchedCount += 1
          }
          notFoundNotables.delete(englishName)
        }
      }
    }
  }
  return JSON.stringify(obj)
})

fs.writeFileSync(outputPath, outLines.join('\n') + '\n', { encoding: 'utf-8' })
console.log(`完了しました。日本語の検索文言を ${addedCount} 件追加しました。`)
console.log(`(うちノータブルパッシブ: ${notableMatchedCount} 件)`)
console.log(`合計 ${outLines.length} 行を ${outputPath} に書き出しました。`)

if (notFoundNotables.size > 0) {
  console.log('')
  console.log('注意: 以下のノータブル名は、英語版データの中に見つかりませんでした（表記が違う可能性があります）:')
  for (const name of notFoundNotables) {
    console.log(' - ' + name)
  }
}